export function parseHierarchyData(): HierarchyItem[] {
  const lines = CSV_RAW_DATA.trim().split('\n');
  const items: HierarchyItem[] = [];
  
  // Skip header
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const parts = line.split(';').map(p => p.trim());
    if (parts.length >= 7) {
      items.push({
        program: parts[0],
        unitEselon1: parts[1],
        kegiatan: parts[2],
        unitEselon2: parts[3],
        prioritasCheck: parts[4],
        kro: parts[5],
        ro: parts[6]
      });
    }
  }
  return items;
}

export const HIERARCHY_DATA: HierarchyItem[] = parseHierarchyData();

// Helper to get unique programs
export function getUniquePrograms(): string[] {
  const set = new Set<string>();
  HIERARCHY_DATA.forEach(item => {
    if (item.program) set.add(item.program);
  });
  return Array.from(set);
}

// Helper to get kegiatans for a program
export function getKegiatansForProgram(program: string): { kegiatan: string; unitEselon1: string }[] {
  const map = new Map<string, string>();
  HIERARCHY_DATA.filter(item => item.program === program).forEach(item => {
    if (item.kegiatan && !map.has(item.kegiatan)) {
      map.set(item.kegiatan, item.unitEselon1);
    }
  });
  return Array.from(map.entries()).map(([kegiatan, unitEselon1]) => ({ kegiatan, unitEselon1 }));
}

// Helper to get KROs for program + kegiatan
export function getKrosForKegiatan(program: string, kegiatan: string): { kro: string; unitEselon2: string; prioritas: string }[] {
  const map = new Map<string, { unitEselon2: string; prioritas: string }>();
  HIERARCHY_DATA.filter(item => item.program === program && item.kegiatan === kegiatan).forEach(item => {
    if (item.kro && !map.has(item.kro)) {
      map.set(item.kro, {
        unitEselon2: item.unitEselon2,
        prioritas: item.prioritasCheck
      });
    }
  });
  return Array.from(map.entries()).map(([kro, val]) => ({
    kro,
    unitEselon2: val.unitEselon2,
    prioritas: val.prioritas
  }));
}

// Helper to get ROs for program + kegiatan + kro
export function getRosForKro(program: string, kegiatan: string, kro: string): string[] {
  const set = new Set<string>();
  HIERARCHY_DATA.filter(item => item.program === program && item.kegiatan === kegiatan && item.kro === kro).forEach(item => {
    if (item.ro) set.add(item.ro);
  });
  return Array.from(set);
}
